                writer.WriteBoolean("supportsOnSeriesDelete", notificationResource.SupportsOnSeriesDeleteOption.Value!.Value);

            if (notificationResource.SupportsOnEpisodeFileDeleteOption.IsSet)
                writer.WriteBoolean("supportsOnEpisodeFileDelete", notificationResource.SupportsOnEpisodeFileDeleteOption.Value!.Value);

            if (notificationResource.SupportsOnEpisodeFileDeleteForUpgradeOption.IsSet)
                writer.WriteBoolean("supportsOnEpisodeFileDeleteForUpgrade", notificationResource.SupportsOnEpisodeFileDeleteForUpgradeOption.Value!.Value);

            if (notificationResource.SupportsOnHealthIssueOption.IsSet)
                writer.WriteBoolean("supportsOnHealthIssue", notificationResource.SupportsOnHealthIssueOption.Value!.Value);

            if (notificationResource.SupportsOnHealthRestoredOption.IsSet)
                writer.WriteBoolean("supportsOnHealthRestored", notificationResource.SupportsOnHealthRestoredOption.Value!.Value);

            if (notificationResource.SupportsOnApplicationUpdateOption.IsSet)
                writer.WriteBoolean("supportsOnApplicationUpdate", notificationResource.SupportsOnApplicationUpdateOption.Value!.Value);

            if (notificationResource.SupportsOnManualInteractionRequiredOption.IsSet)
                writer.WriteBoolean("supportsOnManualInteractionRequired", notificationResource.SupportsOnManualInteractionRequiredOption.Value!.Value);

            if (notificationResource.IncludeHealthWarningsOption.IsSet)
                writer.WriteBoolean("includeHealthWarnings", notificationResource.IncludeHealthWarningsOption.Value!.Value);

            if (notificationResource.TestCommandOption.IsSet)
                if (notificationResource.TestCommandOption.Value != null)
                    writer.WriteString("testCommand", notificationResource.TestCommand);
                else
                    writer.WriteNull("testCommand");
        }
    }
}
